'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/fabmenu/md-gb-fab-menu.js';
import '@material/web/labs/gb/components/fabmenu/md-gb-fab-menu-item.js';
import {FabMenuElement} from '@material/web/labs/gb/components/fabmenu/fab-menu-element.js';
import {FabMenuItemElement} from '@material/web/labs/gb/components/fabmenu/fab-menu-item-element.js';
import type {FabMenuActivateDetail} from '@material/web/labs/gb/components/fabmenu/fab-menu.js';

/**
 * A Material Design component. Wraps <md-gb-fab-menu>.
 * Docs: https://material-web.dev/3.0/components/fab-menu/
 */
export const MdFabMenu = createComponent({
  react: React,
  tagName: 'md-gb-fab-menu',
  elementClass: FabMenuElement,
  events: {
    onActivate: 'activate' as EventName<CustomEvent<FabMenuActivateDetail>>,
    onToggle: 'toggle' as EventName<ToggleEvent>,
  },
});

export type MdFabMenuProps = React.ComponentProps<typeof MdFabMenu>;

/**
 * A Material Design component. Wraps <md-gb-fab-menu-item>.
 * Docs: https://material-web.dev/3.0/components/fab-menu/
 */
export const MdFabMenuItem = createComponent({
  react: React,
  tagName: 'md-gb-fab-menu-item',
  elementClass: FabMenuItemElement,
});

export type MdFabMenuItemProps = React.ComponentProps<typeof MdFabMenuItem>;
